.libPaths(unique(c('/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.5','/home/data/t070721/R/x86_64-pc-linux-gnu-library/4.4',.libPaths())))
suppressPackageStartupMessages({library(data.table);library(qs);library(CellChat)})
root<-'/home/data/t070721/codex_workspace/Bladder Metabolism/mp10_subtype_screen_round1_v2';tt<-file.path(root,'tables');DB<-CellChatDB.human;db<-as.data.table(DB$interaction);db[,LR_id:=interaction_name];top<-fread(file.path(tt,'frozen_MP10_Top20.tsv'))$gene;gcov<-fread(file.path(tt,'signaling_gene_dataset_coverage.tsv'))
parts<-function(v){if(v%in%rownames(DB$complex))return(unname(unlist(DB$complex[v,])[unlist(DB$complex[v,])!='']));v}
db[,ligand_genes:=vapply(ligand,function(z)paste(parts(z),collapse=';'),character(1))];db[,receptor_genes:=vapply(receptor,function(z)paste(parts(z),collapse=';'),character(1))];db[,MP10_gene_overlap:=vapply(seq_len(.N),function(i)any(c(parts(ligand[i]),parts(receptor[i]))%in%top),logical(1))];fwrite(db,file.path(tt,'LR_definitions_v2.tsv'),sep='\t')
files<-list.files(file.path(root,'objects/networks'),pattern='\\.qs$',full.names=TRUE);focus<-list();ios<-list();edges<-list();contrib<-list();params<-list();summ<-list()
for(fp in files){o<-qread(fp);id<-sub('\\.qs$','',basename(fp));prob<-o$net$prob;pv<-o$net$pval;nodes<-dimnames(prob)[[1]];lrs<-dimnames(prob)[[3]];md<-data.table(network_id=id,network_level=o$network_level,scope=o$scope,comparison_type=o$comparison_type,condition=o$condition)
 cd<-copy(o$contributions);cd[,network_id:=id];contrib[[length(contrib)+1]]<-cd;params[[length(params)+1]]<-cbind(md,data.table(data_max=o$params$data_max,n_nodes=length(nodes),n_LR=length(lrs)))
 # Preserve raw numerical probabilities irrespective of internal support. Entire zero-inclusive arrays remain in .qs.
 ix<-which(prob>0,arr.ind=TRUE);if(nrow(ix)){e<-data.table(source=nodes[ix[,1]],target=nodes[ix[,2]],LR_id=lrs[ix[,3]],raw_probability=prob[ix],internal_P=pv[ix]);e[,supported_display_probability:=ifelse(internal_P<.05,raw_probability,0)];edges[[length(edges)+1]]<-cbind(md,e)}
 weights<-apply(ifelse(pv<.05,prob,0),c(1,2),sum);rawsum<-apply(prob,c(1,2),sum)
 allnodes<-sort(unique(o$contributions$node));for(n in allnodes){ok<-n%in%nodes;ios[[length(ios)+1]]<-cbind(md,data.table(node=n,status=if(ok)'computed'else'node_insufficient',outgoing_raw=if(ok)sum(rawsum[n,])else NA_real_,incoming_raw=if(ok)sum(rawsum[,n])else NA_real_,outgoing_supported=if(ok)sum(weights[n,])else NA_real_,incoming_supported=if(ok)sum(weights[,n])else NA_real_))}
 for(i in seq_along(nodes))for(j in seq_along(nodes))summ[[length(summ)+1]]<-cbind(md,data.table(source=nodes[i],target=nodes[j],raw_sum=rawsum[i,j],supported_sum=weights[i,j],n_supported=sum(prob[i,j,]>0&pv[i,j,]<.05)))
 observed_genes<-if(o$scope=='ALL')gcov[observed_in_dataset==TRUE,gene]else gcov[dataset==o$scope&observed_in_dataset==TRUE,gene]
 measurable_dataset<-vapply(seq_len(nrow(db)),function(i)all(c(parts(db$ligand[i]),parts(db$receptor[i]))%in%observed_genes),logical(1))
 measurable_db<-vapply(seq_len(nrow(db)),function(i)all(c(parts(db$ligand[i]),parts(db$receptor[i]))%in%o$genes),logical(1))
 targets<-if(o$network_level=='major')c('B','Plasma')else c('GC B','Memory B','Naive B','IFN-stimulated B','Plasma');epis<-if(o$comparison_type=='epi_state_within_specimen')c('Epi_MP10_low','Epi_MP10_high')else 'Epithelial'
 for(tar in targets)for(ep in epis)for(dir in c('epi_to_TME','TME_to_epi')){src<-if(dir=='epi_to_TME')ep else tar;dst<-if(dir=='epi_to_TME')tar else ep;z<-copy(db[,.(LR_id,interaction_name_2,ligand,receptor,ligand_genes,receptor_genes,pathway_name,MP10_gene_overlap)]);z[,`:=`(source=src,target=dst,TME_type=tar,direction=dir,epi_node=ep,raw_probability=NA_real_,internal_P=NA_real_,supported_display_probability=NA_real_,status='LR_screened_out')]
 measurable<-measurable_db;z[!measurable,status:='gene_unmeasured_or_unmatched'];z[measurable&!measurable_dataset,status:='gene_measurement_unresolved'];measurable<-measurable&measurable_dataset
 if(!(src%in%nodes&&dst%in%nodes))z[,status:='node_insufficient']else{ii<-match(z$LR_id,lrs);ok<-!is.na(ii)&measurable;pr<-prob[src,dst,ii[ok]];pp<-pv[src,dst,ii[ok]];z[ok,`:=`(raw_probability=pr,internal_P=pp,supported_display_probability=ifelse(pp<.05,pr,0),status=ifelse(pr>0&pp<.05,'detected','calculated_not_supported'))]}
 focus[[length(focus)+1]]<-cbind(md,z)
 }}
f<-rbindlist(focus);fwrite(f,file.path(tt,'B_Plasma_LR_all_statuses.tsv.gz'),sep='\t',na='NA');fwrite(rbindlist(edges),file.path(tt,'all_computed_nonzero_LR.tsv.gz'),sep='\t',na='NA');fwrite(rbindlist(ios),file.path(tt,'network_incoming_outgoing.tsv'),sep='\t',na='NA');fwrite(rbindlist(contrib),file.path(tt,'network_cell_contributions.tsv.gz'),sep='\t');fwrite(rbindlist(params),file.path(tt,'network_scaling.tsv'),sep='\t');fwrite(rbindlist(summ),file.path(tt,'network_node_edges.tsv.gz'),sep='\t')
keys<-c('network_level','scope','comparison_type','TME_type','direction','LR_id','interaction_name_2','ligand','receptor','ligand_genes','receptor_genes','MP10_gene_overlap');pairs<-list(epi_state_within_specimen=c('Epi_MP10_low','Epi_MP10_high'),sample_MP10_group_allEpi=c('low','high'),Normal_Tumor=c('Normal','Tumor'),T1_T2=c('T1','T2'));dd<-list()
for(co in names(pairs)){z<-f[comparison_type==co];z[,contrast_group:=if(co=='epi_state_within_specimen')epi_node else condition];l<-z[contrast_group==pairs[[co]][1],c(keys,'raw_probability','internal_P','status'),with=FALSE];h<-z[contrast_group==pairs[[co]][2],c(keys,'raw_probability','internal_P','status'),with=FALSE];setnames(l,c('raw_probability','internal_P','status'),c('prob_low','P_low','status_low'));setnames(h,c('raw_probability','internal_P','status'),c('prob_high','P_high','status_high'));d<-merge(l,h,by=keys,all=TRUE);d[,`:=`(raw_delta=prob_high-prob_low,group0=pairs[[co]][1],group1=pairs[[co]][2])];d[,difference_status:=ifelse(is.finite(raw_delta),'both_computed','not_evaluable_missing_or_screened')];dd[[co]]<-d}
fwrite(rbindlist(dd),file.path(tt,'B_Plasma_LR_contrasts.tsv.gz'),sep='\t',na='NA');cat('DONE',nrow(f),'focus statuses\n')
